BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT json_build_object('run',(SELECT to_jsonb(r) FROM runs r WHERE id='db31b6af-c2a2-44f0-9316-8f8c3492c0f1'),'assessments',(SELECT json_agg(json_build_object('identity_id',i.id,'identity',i.identity-'samples','kind',i.kind,'attempt',to_jsonb(a))) FROM assessment_identities i JOIN assessment_attempts a ON a.identity_id=i.id WHERE i.training_run_id='db31b6af-c2a2-44f0-9316-8f8c3492c0f1'),'checkpoint_policy',(SELECT json_agg(to_jsonb(p)) FROM run_checkpoint_policy p WHERE run_id='db31b6af-c2a2-44f0-9316-8f8c3492c0f1'),'calibration',(SELECT json_agg(to_jsonb(c)) FROM run_threshold_calibration c WHERE run_id='db31b6af-c2a2-44f0-9316-8f8c3492c0f1'),'clinical',(SELECT json_agg(to_jsonb(c)) FROM run_clinical_metrics c WHERE run_id='db31b6af-c2a2-44f0-9316-8f8c3492c0f1'),'metrics',(SELECT json_agg(to_jsonb(c)) FROM run_metrics c WHERE run_id='db31b6af-c2a2-44f0-9316-8f8c3492c0f1'));
COMMIT;
